"""Collector workbench. Every operation is backed by a persistent HTTP API."""
PAGE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Google 采集工作台</title>
<style>
:root{color-scheme:light;--ink:#20334c;--muted:#617389;--line:#d6e0eb;--blue:#245ab5;--bg:#eef3f8;--red:#b33343;--green:#20745a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:"PingFang SC","Microsoft YaHei",system-ui,sans-serif;font-size:14px;line-height:1.6}button,input,select,textarea{font:inherit}button,a,input,select,textarea{outline-offset:3px}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #79a7ee}a{color:var(--blue);overflow-wrap:anywhere}button{cursor:pointer;border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:5px;padding:8px 16px;white-space:nowrap}button.secondary{background:white;color:var(--blue)}button.danger{background:white;color:var(--red);border-color:#d6a7af}button:disabled{cursor:default;opacity:.45}input:not([type=checkbox]),select,textarea{width:100%;border:1px solid #a9bacd;border-radius:4px;padding:8px 10px;background:white;color:var(--ink)}textarea{resize:vertical;min-height:90px}input[type=checkbox]{accent-color:var(--blue);width:17px;height:17px;vertical-align:middle;margin-right:7px}label{display:block;font-weight:600;margin-bottom:6px}fieldset{border:0;margin:0;padding:0}legend{font-weight:600;margin-bottom:7px}h1{font-size:27px;letter-spacing:-.5px;margin:0 0 6px}h2{font-size:19px;margin:0 0 16px}h3{font-size:16px;margin:0 0 10px}p{max-width:80ch;margin:8px 0 16px}.muted,.help{color:var(--muted)}.help{font-size:12px;margin:5px 0 0}.shell{display:grid;grid-template-columns:196px minmax(0,1fr);min-height:100vh}aside{padding:30px 20px;background:#e3ebf5;border-right:1px solid #c8d6e7;position:sticky;top:0;height:100vh}.brand{font-size:21px;font-weight:750;margin-bottom:32px}.brand small{font-size:12px;color:var(--muted);display:block;font-weight:400;margin-top:5px}nav{display:grid;gap:7px}nav a{text-decoration:none;padding:10px 13px;border-radius:4px;color:var(--ink)}nav a[aria-current=page]{background:var(--blue);color:white}.aside-foot{margin-top:38px;font-size:12px;color:var(--muted)}main{padding:28px 34px;max-width:1600px;width:100%;margin:0 auto;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px;gap:18px}.run{padding:7px 12px;border:1px solid var(--line);border-radius:4px;background:white;font-size:12px}.notice{padding:10px 14px;background:#dde9fc;border-left:3px solid var(--blue);margin-bottom:18px;overflow-wrap:anywhere}.notice.error{background:#fbe8eb;border-color:var(--red);color:var(--red)}.notice:empty{display:none}.panel{background:white;border:1px solid var(--line);border-radius:6px;padding:22px;margin-bottom:20px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:#fff;border:1px solid var(--line);border-radius:6px;margin-bottom:22px}.metric{padding:20px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric strong{display:block;font-size:31px;font-weight:700;font-variant-numeric:tabular-nums;line-height:1.4}.metric span{color:var(--muted)}.sources{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.source{padding:20px;border-top:4px solid var(--blue);background:white;margin-bottom:22px;border-radius:4px}.source.news{border-color:var(--green)}.source.trends{border-color:#896098}.source dl{display:grid;grid-template-columns:1fr auto;margin:16px 0 0;gap:6px}.source dt{color:var(--muted)}.source dd{margin:0;font-variant-numeric:tabular-nums}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 24px}.wide{grid-column:1/-1}.checks{display:flex;gap:18px;flex-wrap:wrap}.checks label{font-weight:400}.actions,.filters,.pager{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.actions{margin-top:18px}.filters{margin-bottom:14px;align-items:flex-end}.filters label{font-size:12px}.filters>div{min-width:130px;flex:1}.filters .query-filter{flex:2}.filters button{margin-bottom:0}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;min-width:700px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;color:var(--muted);background:#f6f9fc;font-weight:600}td{font-size:13px}.nowrap{white-space:nowrap}.badge{display:inline-block;font-size:12px;padding:2px 7px;border-radius:4px;background:#eaf0f6}.badge.ok{color:var(--green);background:#e7f3ee}.badge.err{color:var(--red);background:#fbe8eb}.task-query{max-width:300px;overflow-wrap:anywhere;font-weight:600}.mini{padding:4px 8px;font-size:12px}.row-actions{display:flex;gap:6px;flex-wrap:wrap;min-width:160px}.pager{justify-content:flex-end;margin-top:15px}.pager span{margin-right:auto;color:var(--muted)}.result-list{display:grid;gap:14px}.result{border:1px solid var(--line);border-left:4px solid #97afd0;padding:15px 18px;border-radius:4px}.result.news{border-left-color:var(--green)}.result.trends{border-left-color:#896098}.result h3{margin:8px 0;font-size:16px}.result-meta{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted)}.result p{font-size:13px;overflow-wrap:anywhere;margin:8px 0}.result details{margin-top:10px}.result ul{padding-left:20px}.empty{padding:30px;text-align:center;color:var(--muted)}.foot{color:var(--muted);font-size:12px}.tabs{display:flex;gap:9px;margin-bottom:18px}.tabs button[aria-pressed=true]{background:var(--blue);color:white}pre{font-family:ui-monospace,SFMono-Regular,monospace;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto;margin:12px 0}.json-dialog{width:min(950px,94vw);max-height:90vh;border:1px solid #a9bacd;border-radius:7px;padding:22px;color:var(--ink)}dialog::backdrop{background:#20334c80}.dialog-top{display:flex;justify-content:space-between;align-items:center;gap:12px}.switch-row{padding:14px 0;border-bottom:1px solid var(--line)}.switch-row label{margin:0}.limitations{font-size:13px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:1000px){main{padding:24px 20px}.shell{grid-template-columns:165px minmax(0,1fr)}aside{padding:25px 14px}.sources{gap:10px}.metric strong{font-size:26px}}@media(max-width:740px){.shell{display:block}aside{height:auto;position:static;padding:15px 18px;border-bottom:1px solid var(--line)}.brand{margin:0 0 12px;font-size:18px}.brand small,.aside-foot{display:none}nav{display:flex;gap:5px;flex-wrap:wrap}nav a{padding:7px 13px}main{padding:20px 14px}.top{align-items:flex-start}h1{font-size:23px}.metrics{grid-template-columns:repeat(2,1fr)}.metric{padding:13px}.metric:nth-child(2){border-right:0}.metric:nth-child(-n+2){border-bottom:1px solid var(--line)}.sources,.grid{grid-template-columns:1fr}.source{margin-bottom:5px}.sources{margin-bottom:20px}.panel{padding:17px}.filters>div{min-width:calc(50% - 12px)}.wide{grid-column:auto}.run{max-width:150px}.result{padding:12px}.filters .query-filter{flex:1}}
.run-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.run-actions button{min-width:156px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px}.section-head h2{margin:0}.latest-list .result{background:white}.latest-list .result h3{font-size:17px}.latest-list .result .help{overflow-wrap:anywhere}.advanced{margin:18px 0}.advanced>summary{cursor:pointer;color:var(--muted);padding:9px 0}.advanced[open]>summary{margin-bottom:12px}.auto-help{margin:0 0 18px}.loading{padding:24px;color:var(--muted);background:white;border:1px solid var(--line)}.result-list[aria-busy=true]{opacity:.65}@media(max-width:740px){.top{flex-direction:column}.run-actions{width:100%;justify-content:space-between}.run-actions button{min-width:0}.section-head{flex-wrap:wrap}}
</style></head><body>
<div class="shell"><aside><div class="brand">Google 采集<span aria-hidden="true"> / </span><small>网页、新闻与热门话题</small></div><nav aria-label="主导航"><a href="#overview" data-view="overview">首页</a><a href="#tasks" data-view="tasks">任务</a><a href="#results" data-view="results">采集数据</a><a href="#whale" data-view="whale">平台上传</a><a href="#settings" data-view="settings">设置</a></nav><div class="aside-foot">链接和结构化数据优先<br><a href="/articles">历史正文</a><br><a href="/stats">历史实验统计</a></div></aside>
<main><header class="top"><div><h1 id="pageTitle">采集总览</h1><div class="muted" id="pageSubtitle">最近 24 小时，按实际持久化记录统计</div></div><div class="run-actions"><span class="run" id="runState">读取运行设置…</span><button type="button" id="autoToggle" disabled>读取自动采集状态…</button></div></header><div id="notice" class="notice" role="status" aria-live="polite"></div>
<section id="overviewView"><p class="help auto-help" id="autoHelp">关闭自动采集会保留所有已采集数据；手动任务单独管理。</p><div class="section-head"><h2>最新采集数据</h2><div class="actions" style="margin:0"><button type="button" id="refreshLatest" class="secondary">刷新数据</button><a href="#results">查看全部数据 / 筛选 / 导出</a></div></div><p class="help" style="margin-bottom:14px">点击标题打开原网页。这里保存的是链接、标题和摘要；文章正文当前未采集。</p><div id="latestRows" class="result-list latest-list"><div class="loading">正在读取已采集数据…</div></div><details class="advanced"><summary>查看采集统计与异常</summary><div class="metrics"><div class="metric"><span>新增唯一链接</span><strong id="newLinks">—</strong><small class="muted">与全部留存历史去重</small></div><div class="metric"><span>采集请求</span><strong id="attempts">—</strong><small class="muted">缓存复用不重复计请求</small></div><div class="metric"><span>请求成功率</span><strong id="successRate">—</strong><small class="muted">含成功空结果</small></div><div class="metric"><span>失败请求</span><strong id="failures">—</strong><small id="captchaHint" class="muted">—</small></div></div><div class="sources" id="sourceStats"></div>
<div class="panel"><h2>异常分布</h2><div class="table-scroll"><table><thead><tr><th>来源</th><th>分类</th><th>错误码</th><th>最近 24 小时请求数</th></tr></thead><tbody id="errorGroups"></tbody></table></div></div>
<div class="panel"><h2>最近异常</h2><div class="help">显示最新 15 条留存异常；可能早于最近 24 小时。</div><div class="table-scroll"><table><thead><tr><th>时间</th><th>来源 / 查询</th><th>异常</th><th>HTTP</th><th>数据</th></tr></thead><tbody id="recentErrors"></tbody></table></div></div><p class="foot">各来源的链接可能重叠；首次发现贡献之和等于全局新增。新闻包装跳转地址仍可能与出版社地址分别计数。</p></details></section>
<section id="tasksView" hidden><div class="panel"><h2>创建采集任务</h2><form id="taskForm"><div class="grid"><div class="wide"><label for="keywords">关键词（每行一个，最多 50 个）</label><textarea id="keywords" placeholder="solar energy research&#10;人工智能政策" maxlength="15500"></textarea><p class="help">Web 和 News 需要关键词；纯 Trends 可以留空，采集当前热门话题，关键词不会过滤趋势。</p></div><fieldset class="wide"><legend>采集来源</legend><div class="checks"><label><input type="checkbox" name="taskSource" value="google_web" checked>Google Web</label><label><input type="checkbox" name="taskSource" value="google_news">Google News</label><label><input type="checkbox" name="taskSource" value="google_trends">Google Trends</label></div></fieldset><div id="webRegionField"><label for="webRegion">Web 搜索地区</label><select id="webRegion"></select></div><div id="webLanguageField"><label for="webLanguage">Web 语言</label><select id="webLanguage"><option value="auto">按关键词自动选择 en / zh</option><option value="en">英语 en</option><option value="zh">中文 zh</option></select></div><div id="newsLocaleField" hidden><label for="newsLocale">News 地区及语言</label><select id="newsLocale"></select></div><div id="trendsGeoField" hidden><label for="trendsGeo">Trends 热门话题地区</label><select id="trendsGeo"></select></div></div><p><label class="check"><input type="checkbox" id="taskWhaleUpload"> 同时加入 Whale 上传队列</label></p><div class="actions"><button type="submit" id="createStart" value="start">创建并启动</button><button type="submit" id="createDraft" class="secondary" value="draft">保存待启动</button></div></form></div>
<div class="panel"><h2>我的任务</h2><p class="help">手动创建的任务在这里管理；系统自动任务可切换“任务类型”查看，顶部按钮统一开关自动采集。</p><form class="filters" id="taskFilters"><div><label for="taskKind">任务类型</label><select id="taskKind"><option value="manual">手动创建</option><option value="automatic">自动采集任务</option><option value="all">全部</option></select></div><div><label for="taskStatus">任务状态</label><select id="taskStatus"><option value="">全部</option><option value="active">运行中</option><option value="paused">暂停 / 待启动</option><option value="stopped">已停止</option><option value="failed">失败</option></select></div><div class="query-filter"><label for="taskQ">关键词</label><input id="taskQ" type="search"></div><button type="submit" class="secondary">筛选任务</button></form><div class="help">任务会按间隔重复采集。暂停或停止后保留数据，已发出的请求允许完成；自动任务服从顶部总开关。</div><div class="table-scroll"><table><thead><tr><th>任务 / 参数</th><th>来源</th><th>状态</th><th>请求 / 缓存</th><th>首次发现贡献</th><th>操作</th></tr></thead><tbody id="taskRows"></tbody></table></div><div class="pager"><span id="taskCount"></span><button id="taskPrev" class="secondary" type="button">上一页</button><button id="taskNext" class="secondary" type="button">下一页</button></div></div></section>
<section id="resultsView" hidden><div class="panel"><div class="tabs" role="group" aria-label="数据视图"><button id="resultTab" class="secondary" aria-pressed="true">结构化结果</button><button id="requestTab" class="secondary" aria-pressed="false">采集请求 / JSON</button></div><form id="resultFilters"><div class="filters"><div><label for="resultSource">来源</label><select id="resultSource"><option value="">全部来源</option><option value="google_web">Google Web</option><option value="google_news">Google News</option><option value="google_trends">Google Trends</option></select></div><div class="query-filter"><label for="resultQ">关键词 / 标题 / 链接</label><input type="search" id="resultQ"></div></div><details class="advanced"><summary>更多筛选：任务、状态和日期</summary><div class="filters"><div><label for="resultCampaign">任务 ID（可从任务页选取）</label><input id="resultCampaign" placeholder="全部任务"></div><div><label for="resultStatus">请求状态</label><select id="resultStatus"><option value="">全部</option><option value="success">成功</option><option value="error">异常</option></select></div></div><div class="filters"><div><label for="resultSince">采集开始日期（UTC，含当日）</label><input type="date" id="resultSince"></div><div><label for="resultUntil">采集结束日期（UTC，含当日）</label><input type="date" id="resultUntil"></div><label><input type="checkbox" id="newOnly">仅首次发现新链接</label></div></details><div class="actions"><button type="submit">应用筛选</button><button id="resetFilters" class="secondary" type="button">重置筛选</button></div></form><div class="actions"><button type="button" id="exportJson" class="secondary">导出全部筛选 JSONL</button><button type="button" id="exportCsv" class="secondary">导出全部筛选 CSV</button></div><p class="help" id="resultHelp">Trends 显示热门话题及报道，话题数不计为链接数。JSONL 逐行保存完整结构化数据。</p></div><div id="resultRows" class="result-list"><div class="loading">正在读取已采集数据…</div></div><div class="pager"><span id="resultCount"></span><button id="resultPrev" class="secondary" type="button">上一页</button><button id="resultNext" class="secondary" type="button">下一页</button></div></section>
<section id="whaleView" hidden>
<div class="panel"><h2>Whale 数据平台</h2><p id="whaleConnection" class="muted">读取对接状态…</p><form id="whaleSettingsForm"><div class="checks"><label><input type="checkbox" id="whaleUploadSwitch">允许上传已排队的数据</label><label><input type="checkbox" id="whaleClaimSwitch">接收平台任务并采集</label></div><p class="help">两个开关独立保存。接收平台任务会执行新采集；顶部自动采集开关管理系统自动任务。正文保持关闭。</p><div class="actions"><button id="saveWhaleSettings">保存平台开关</button></div></form><p class="help" id="whaleRuntime"></p></div>
<div class="metrics"><div class="metric"><strong id="whalePending">0</strong><span>待上传</span></div><div class="metric"><strong id="whaleReceived">0</strong><span>平台已接收</span></div><div class="metric"><strong id="whaleDuplicate">0</strong><span>平台回报重复</span></div><div class="metric"><strong id="whaleRejected">0</strong><span>拒收</span></div></div>
<div class="panel"><h2>上传已采集链接</h2><p class="help">保存链接、标题、摘要和来源等搜索详情。不下载正文，不补造发布时间；平台接收回执不代表最终业务入库。</p><form id="whaleUploadForm"><div class="grid"><div><label for="whaleSource">来源</label><select id="whaleSource"><option value="">全部来源</option><option value="google_web">Google Web</option><option value="google_news">Google News</option><option value="google_trends">Google Trends 报道</option></select></div><div><label for="whaleLimit">本次最多上传链接数</label><input id="whaleLimit" type="number" min="1" max="10000" value="100"></div><div><label for="whaleQuery">关键词、标题或链接筛选</label><input id="whaleQuery" placeholder="留空选择最新数据"></div><div><label for="whaleCampaign">指定采集任务 ID（可留空）</label><input id="whaleCampaign"></div><div><label for="whaleSince">采集开始日期</label><input id="whaleSince" type="date"></div><div><label for="whaleUntil">采集结束日期</label><input id="whaleUntil" type="date"></div><div class="wide"><label><input type="checkbox" id="whaleNewOnly" checked>仅首次发现的新链接</label></div></div><div class="actions"><button id="createWhaleUpload" type="submit" value="start">加入上传队列</button><button class="secondary" type="submit" value="draft">保存待上传</button></div></form></div>
<div class="panel"><div class="section-head"><h2>上传与平台任务</h2><button id="refreshWhale" class="secondary">刷新</button></div><div class="table-scroll"><table><thead><tr><th>任务</th><th>状态</th><th>链接数</th><th>已接收 / 重复</th><th>待上传 / 拒收</th><th>操作</th></tr></thead><tbody id="whaleJobs"></tbody></table></div><div class="pager"><span id="whaleJobCount"></span><button id="whalePrev" class="secondary">上一页</button><button id="whaleNext" class="secondary">下一页</button></div></div>
<dialog id="whaleReceiptDialog" class="json-dialog"><div class="dialog-top"><strong>平台回执与实际上传数据</strong><button id="closeWhaleReceipts" class="secondary">关闭</button></div><p class="help">queued 为已接收队列，accepted 为接口接受，duplicate 为重复；最终入库状态尚未核验。每页最多 50 条。</p><pre id="whaleReceipts"></pre><div class="pager"><button id="whaleReceiptPrev" class="secondary">上一页</button><button id="whaleReceiptNext" class="secondary">下一页</button></div></dialog>
</section>
<section id="settingsView" hidden><div class="panel"><h2>采集设置</h2><form id="settingsForm"><div class="switch-row"><label><input type="checkbox" id="bodySwitch">获取文章正文</label><p class="help">默认关闭。开启后额外下载文章；关闭后取消正在运行的正文进程。链接入库和统计不依赖正文是否成功。</p></div><div class="switch-row"><label><input type="checkbox" id="continuousSwitch">自动采集</label><p class="help">自动补充关键词任务。关闭时自动任务停止后续请求；手动任务仍按各自状态采集。</p></div><details class="advanced"><summary>高级设置：来源、关键词、地区和采集间隔</summary><div class="grid" style="margin-top:20px"><fieldset class="wide"><legend>持续采集来源</legend><div class="checks"><label><input type="checkbox" name="continuousSource" value="google_web">Google Web</label><label><input type="checkbox" name="continuousSource" value="google_news">Google News</label><label><input type="checkbox" name="continuousSource" value="google_trends">Google Trends</label></div></fieldset><div class="wide"><label for="continuousKeywords">持续关键词（每行一个）</label><textarea id="continuousKeywords" placeholder="留空使用内置关键词库，最多 1000 条"></textarea><p class="help">自定义词从后续新供给任务使用；已生成的任务保留原关键词。Trends 不受关键词过滤。</p></div><div><label for="settingsWebRegion">默认 Web 地区</label><select id="settingsWebRegion"></select></div><div><label for="settingsWebLanguage">默认 Web 语言</label><select id="settingsWebLanguage"><option value="auto">按关键词自动 en / zh</option><option value="en">英语 en</option><option value="zh">中文 zh</option></select></div><div><label for="settingsNewsLocales">持续 News 地区 / 语言（逗号分隔）</label><input id="settingsNewsLocales" required><p class="help" id="newsEditionsHint"></p></div><div><label for="settingsTrendsGeos">持续 Trends 地区（逗号分隔）</label><input id="settingsTrendsGeos" required><p class="help">例如 US,SG；地区可用性取决于 Google RSS。</p></div><div><label for="webPages">Web 最大页数（1–11）</label><input id="webPages" type="number" min="1" max="11" required></div><div><label for="newsInterval">News 重采 / 缓存间隔（秒）</label><input id="newsInterval" type="number" min="300" max="86400" required></div><div><label for="trendsInterval">Trends 重采 / 缓存间隔（秒）</label><input id="trendsInterval" type="number" min="60" max="86400" required></div></div></details><div class="actions"><button type="submit" id="saveSettings">保存并应用</button><span class="help" id="settingsSaved"></span></div><p class="help">保存到数据库，后续采集批次生效，持续供给最多 30 秒读取。旧缓存保留到原到期时间；任务内明确设置的地区优先于默认值。并发及代理限速由部署管理，此页不支持修改。</p></form></div><div class="panel limitations"><h2>当前支持范围</h2><p>Web：自然网页结果及上游实际提供的字段。News：Google News 搜索 RSS；无法离线解析的 Google 跳转链接明确标记，列表顺序不是 Google 排名。</p><p>Trends：Trending Now 当前热门话题及相关报道；搜索量保留原始近似标记。关键词历史热度曲线、区域兴趣、高级商业模块和第三方 RSS 尚未支持。缺失数据为未知 / null。</p><p><a href="/articles">查看历史正文</a>　<a href="/stats">查看历史实验统计</a></p></div></section>
<footer class="foot" id="updated">正在连接后端…</footer></main></div>
<dialog id="jsonDialog" class="json-dialog"><div class="dialog-top"><strong>完整请求 JSON</strong><button id="closeJson" class="secondary">关闭</button></div><div class="actions"><button id="downloadJson" class="secondary">下载此请求 JSON</button></div><pre id="jsonText"></pre></dialog>
<script>
const $=id=>document.getElementById(id), names={google_web:'Google Web',google_news:'Google News',google_trends:'Google Trends'}, states={active:'运行中',paused:'暂停 / 待启动',stopped:'已停止',failed:'失败'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>Number(v||0).toLocaleString('zh-CN'),rate=v=>v==null?'未知':(v*100).toFixed(1)+'%',time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'未知';
const safeLink=v=>typeof v==='string'&&/^https?:\/\//i.test(v)?esc(v):'#';
let view='overview',taskOffset=0,resultOffset=0,resultMode='results',taskTotal=0,resultTotal=0,currentJson=null,settingsDirty=false,settingsLoaded=false,autoEnabled=null,taskSeq=0,resultSeq=0;
function notice(msg,error=false){$('notice').textContent=msg;$('notice').className='notice'+(error?' error':'')}
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'请求失败 '+r.status);return d}
function showView(){const id=location.hash.slice(1);view=['overview','tasks','results','whale','settings'].includes(id)?id:'overview';for(const x of ['overview','tasks','results','whale','settings']){$(x+'View').hidden=x!==view;document.querySelector(`[data-view="${x}"]`).setAttribute('aria-current',x===view?'page':'false')}$('pageTitle').textContent={overview:'采集数据与控制',tasks:'任务管理',results:'已采集数据',whale:'Whale 平台上传',settings:'运行设置'}[view];$('pageSubtitle').textContent={overview:'查看真实数据，在这里开启或关闭自动采集',tasks:'从关键词和来源创建任务，管理实际采集状态',results:'网页、新闻与热门话题的持久化结构化记录',whale:'控制上传与平台任务，查看实际数据及回执',settings:'保存后生效，关闭采集不删除历史数据'}[view];refreshView()}
function sourceFields(){const selected=[...document.querySelectorAll('[name=taskSource]:checked')].map(x=>x.value);for(const [id,s] of [['webRegionField','google_web'],['webLanguageField','google_web'],['newsLocaleField','google_news'],['trendsGeoField','google_trends']])$(id).hidden=!selected.includes(s)}
document.querySelectorAll('[name=taskSource]').forEach(x=>x.addEventListener('change',sourceFields));
async function loadSettings(force=false){const s=await api('/api/collector-settings');autoEnabled=s.continuous_enabled;$('runState').textContent=autoEnabled?'自动采集中':'自动采集已关闭';$('autoToggle').textContent=autoEnabled?'关闭自动采集':'开启自动采集';$('autoToggle').className=autoEnabled?'danger':'';if(!autoToggleBusy)$('autoToggle').disabled=false;$('autoHelp').textContent=autoEnabled?'自动采集正在运行。关闭后保留全部数据；手动任务单独管理。':'自动采集已关闭，已采集数据仍可查看和导出。手动任务单独管理。';if(!settingsLoaded){for(const id of ['webRegion','trendsGeo','settingsWebRegion'])$(id).innerHTML=s.regions.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('newsLocale').innerHTML=s.news_editions.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('webRegion').value=s.web_region;$('webLanguage').value=s.web_language;$('trendsGeo').value=s.trends_geos[0];$('newsLocale').value=s.news_locales[0];$('newsEditionsHint').textContent='支持 '+s.news_editions.join(', ')}if(!settingsDirty||force){$('bodySwitch').checked=s.content_fetch_enabled;$('continuousSwitch').checked=s.continuous_enabled;document.querySelectorAll('[name=continuousSource]').forEach(x=>x.checked=s.continuous_sources.includes(x.value));$('continuousKeywords').value=s.continuous_keywords.join('\n');$('settingsWebRegion').value=s.web_region;$('settingsWebLanguage').value=s.web_language;$('settingsNewsLocales').value=s.news_locales.join(',');$('settingsTrendsGeos').value=s.trends_geos.join(',');$('webPages').value=s.web_max_pages;$('newsInterval').value=s.news_interval_seconds;$('trendsInterval').value=s.trends_interval_seconds;$('settingsSaved').textContent=s.updated_at?'上次保存 '+time(s.updated_at):'';settingsDirty=false}settingsLoaded=true;return s}
async function loadOverview(){const s=await api('/api/serp/stats');$('newLinks').textContent=fmt(s.links.new_last_24h);$('attempts').textContent=fmt(s.requests.attempts);$('successRate').textContent=rate(s.requests.success_rate);$('failures').textContent=fmt(s.requests.failed);$('captchaHint').textContent='明确验证码 '+fmt(s.requests.explicit_captcha);const desc={google_web:'自然结果、摘要与实际排名',google_news:'新闻 RSS、媒体与发布时间',google_trends:'当前热门话题与相关报道'};$('sourceStats').innerHTML=Object.entries(s.sources).map(([k,x])=>`<div class="source ${k.replace('google_','')}"><h3>${names[k]}</h3><span class="muted">${desc[k]}</span><dl><dt>首次发现贡献</dt><dd><strong>${fmt(x.first_discovery_contribution)}</strong></dd><dt>本来源首次收录链接</dt><dd>${fmt(x.unique_new_urls)}</dd><dt>请求 / 成功率</dt><dd>${fmt(x.attempts)} / ${rate(x.success_rate)}</dd><dt>异常 / 验证码</dt><dd>${fmt(x.failed)} / ${fmt(x.explicit_captcha)}</dd></dl></div>`).join('');$('errorGroups').innerHTML=s.errors.map(x=>`<tr><td>${names[x.source]}</td><td>${esc(x.classification)}</td><td>${esc(x.error_code||'未知')}</td><td>${fmt(x.count)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">最近 24 小时没有异常请求。</td></tr>';$('recentErrors').innerHTML=s.recent_errors.map(x=>`<tr><td class="nowrap">${time(x.completed_at)}</td><td>${names[x.source]}<div>${esc(x.query)}</div></td><td>${esc(x.classification)}<div class="help">${esc(x.error_code||'未知')}</div></td><td>${esc(x.http_status??'未知')}</td><td><button class="mini secondary" data-json="${esc(x.id)}">查看 JSON</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有留存异常。</td></tr>'}
function taskParams(){return new URLSearchParams({kind:$('taskKind').value,status:$('taskStatus').value,q:$('taskQ').value,offset:taskOffset,limit:20})}
async function loadTasks(){const seq=++taskSeq,d=await api('/api/serp/tasks?'+taskParams());if(seq!==taskSeq)return;taskTotal=d.total;$('taskRows').innerHTML=d.tasks.map(x=>{const opts=Object.entries(x.options||{}).map(([k,v])=>`${k}: ${v}`).join(' / ');let buttons=x.status==='active'?'<button class="mini secondary" data-op="pause">暂停</button>':x.status==='paused'?(x.started?'<button class="mini" data-op="resume">继续</button>':'<button class="mini" data-op="start">启动</button>'):'<button class="mini" data-op="start">重新启动</button>';if(['active','paused','failed'].includes(x.status))buttons+='<button class="mini danger" data-op="stop">停止</button>';return `<tr data-cid="${esc(x.id)}"><td><div class="task-query">${esc(x.query)}</div>${x.aliases.length?`<div class="help">另有 ${fmt(x.aliases.length)} 个关键词</div><details><summary>查看全部关键词</summary><div>${x.aliases.map(esc).join('<br>')}</div></details>`:''}<div class="help">${esc(opts||'使用默认地区')}<br>${esc(x.id)}</div><details><summary>任务详情</summary><div class="help">创建 ${time(x.created_at)}<br>更新 ${time(x.updated_at)}<br>最近请求 ${time(x.last_request_at)}<br>异常 ${esc(x.last_error||'无')}</div></details></td><td>${x.sources.map(s=>esc(names[s]||s)).join('<br>')}</td><td><span class="badge ${x.status==='active'?'ok':''}">${x.automatic&&autoEnabled===false&&x.status==='active'?'自动采集已关闭':x.status==='paused'&&!x.started?'待启动':states[x.status]||esc(x.status)}</span>${x.automatic?'<div class="help">由顶部自动采集按钮控制</div>':''}</td><td>${fmt(x.requests)} / ${fmt(x.cached)}<div class="help">成功 ${fmt(x.successful)}</div></td><td>${fmt(x.new_links)}</td><td><div class="row-actions">${buttons}<button class="mini secondary" data-results="${esc(x.id)}">查看结果</button></div></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">没有符合条件的任务。填写上方表单创建任务。</td></tr>';$('taskCount').textContent=`共 ${fmt(d.total)} 个任务，当前 ${d.total?taskOffset+1:0}–${Math.min(taskOffset+20,d.total)}`;$('taskPrev').disabled=taskOffset===0;$('taskNext').disabled=taskOffset+20>=d.total}
$('taskForm').addEventListener('submit',async e=>{e.preventDefault();const start=e.submitter?.value!=='draft',sources=[...document.querySelectorAll('[name=taskSource]:checked')].map(x=>x.value),opts={};if(sources.includes('google_web'))Object.assign(opts,{web_region:$('webRegion').value,web_language:$('webLanguage').value});if(sources.includes('google_news'))opts.news_locale=$('newsLocale').value;if(sources.includes('google_trends'))opts.trends_geo=$('trendsGeo').value;$('createStart').disabled=$('createDraft').disabled=true;try{const d=await api('/api/serp/tasks',{keywords:$('keywords').value.split('\n').map(x=>x.trim()).filter(Boolean),sources,options:opts,start,upload_to_whale:$('taskWhaleUpload').checked});notice(start?'任务已创建并启动：'+d.campaign_id:'任务已保存，可在下方启动：'+d.campaign_id);$('taskKind').value='manual';$('taskStatus').value='';$('taskQ').value='';taskOffset=0;await loadTasks()}catch(e){notice(e.message,true)}finally{$('createStart').disabled=$('createDraft').disabled=false}});
$('taskFilters').addEventListener('submit',e=>{e.preventDefault();taskOffset=0;loadTasks().catch(e=>notice(e.message,true))});
$('taskRows').addEventListener('click',async e=>{const b=e.target.closest('button[data-op]');if(!b)return;const cid=b.closest('[data-cid]').dataset.cid;b.disabled=true;try{const op=b.dataset.op;await api(`/api/serp/tasks/${cid}/${op}`,{});notice({pause:'任务已暂停',stop:'任务已停止',start:'任务已启动',resume:'任务已继续'}[op]);await loadTasks()}catch(e){notice(e.message,true)}finally{b.disabled=false}});
$('taskPrev').onclick=()=>{taskOffset=Math.max(0,taskOffset-20);loadTasks().catch(e=>notice(e.message,true))};$('taskNext').onclick=()=>{taskOffset+=20;loadTasks().catch(e=>notice(e.message,true))};
function resultParams(){const f={source:$('resultSource').value,campaign_id:$('resultCampaign').value.trim(),q:$('resultQ').value.trim(),status:$('resultStatus').value,new_only:String($('newOnly').checked)};if($('resultSince').value)f.since=$('resultSince').value+'T00:00:00Z';if($('resultUntil').value){const end=new Date($('resultUntil').value+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1);f.until=end.toISOString()}return new URLSearchParams(f)}
async function loadResults(){const seq=++resultSeq,p=resultParams();p.set('offset',resultOffset);p.set('limit',25);p.set('count_total','false');$('resultRows').setAttribute('aria-busy','true');if(!$('resultRows').textContent.trim())$('resultRows').innerHTML='<div class="loading">正在读取已采集数据…</div>';const d=await api('/api/serp/'+(resultMode==='requests'?'browse-requests':'results')+'?'+p);if(seq!==resultSeq)return;$('resultRows').setAttribute('aria-busy','false');resultTotal=d.total;if(resultMode==='requests'){$('resultRows').innerHTML=`<div class="panel table-scroll"><table><thead><tr><th>时间 / 来源</th><th>查询 / 参数</th><th>状态</th><th>新增链接</th><th>JSON</th></tr></thead><tbody>${d.rows.map(x=>`<tr><td>${time(x.completed_at)}<div>${names[x.source]}</div></td><td>${esc(x.query)}<div class="help">${esc(JSON.stringify(x.response.search_parameters))}</div></td><td><span class="badge ${['results','empty'].includes(x.status)?'ok':'err'}">${esc(x.status)}</span><div class="help">HTTP ${esc(x.http_status??'未知')} ${esc(x.error_code||'')}</div></td><td>${fmt(x.response.new_unique_links)}</td><td><button class="mini secondary" data-json="${esc(x.id)}">查看完整 JSON</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有符合筛选条件的请求。尝试扩大日期范围或选择其他任务。</td></tr>'}</tbody></table></div>`}else{$('resultRows').innerHTML=d.rows.map(x=>{const a=x.data,tr=x.source==='google_trends';let body=tr?`<h3>${esc(a.keyword||'未知热门话题')}</h3><p>搜索量标记：${esc(a.approx_traffic??'未知')}　话题发布时间：${esc(a.published_at??'未知')}</p><ul>${(a.articles||[]).map(b=>`<li><a href="${safeLink(b.link)}" target="_blank" rel="noopener noreferrer">${esc(b.title||b.link)}</a> <span class="help">${esc(b.publisher||'未知媒体')}${b.is_new_url?' / 新链接':''}${b.link_status==='google_news_redirect'?' / 未解析 Google 跳转':''}</span></li>`).join('')||'<li class="muted">上游没有提供相关报道链接，话题仍已保存。</li>'}</ul>`:`<h3><a href="${safeLink(a.link)}" target="_blank" rel="noopener noreferrer">${esc(a.title||a.link||'未知标题')}</a></h3><div class="help">${esc(a.link)}</div><p>${esc(a.snippet??'摘要未知')}</p><div class="help">${esc(a.publisher||a.domain||'未知来源')}　${x.source==='google_web'?'Google 排名 '+esc(a.position??'未知'):'RSS 顺序 '+esc(a.feed_position??'未知')+'（非 Google 排名）'}　${esc(a.date??'发布时间未知')}${a.link_status==='google_news_redirect'?'　未解析的 Google 新闻跳转链接':''}</div>`;return `<article class="result ${x.source.replace('google_','')}"><div class="result-meta"><span class="badge">${names[x.source]}</span><span>${time(x.completed_at)}</span><span>查询 ${esc(x.query)}</span>${a.is_new_url?'<span class="badge ok">首次发现新链接</span>':''}<button class="mini secondary" data-json="${esc(x.id)}">完整请求 JSON</button></div>${body}<details><summary>此结果结构化字段</summary><pre>${esc(JSON.stringify(a,null,2))}</pre></details></article>`}).join('')||'<div class="panel empty">没有符合筛选条件的结果。创建任务或扩大筛选范围；异常请求可在“采集请求 / JSON”中查看。</div>'}$('resultCount').textContent=`显示第 ${d.rows.length?resultOffset+1:0}–${resultOffset+d.rows.length} ${resultMode==='requests'?'次请求':'条数据'}${d.has_more?'，还有更多':''}`;$('resultPrev').disabled=resultOffset===0;$('resultNext').disabled=!d.has_more}
$('resultFilters').addEventListener('submit',e=>{e.preventDefault();resultOffset=0;loadResults().catch(e=>notice(e.message,true))});$('resetFilters').onclick=()=>{$('resultFilters').reset();resultOffset=0;loadResults().catch(e=>notice(e.message,true))};
function switchMode(mode){resultMode=mode;resultOffset=0;$('resultTab').setAttribute('aria-pressed',mode==='results');$('requestTab').setAttribute('aria-pressed',mode==='requests');$('resultHelp').textContent=mode==='results'?'Trends 显示热门话题及报道，话题数不计为链接数。JSONL 逐行保存结构化数据。':'请求导出含完整响应 JSON；关键词筛选匹配查询文本。缓存共享的原始请求只导出一次。';loadResults().catch(e=>notice(e.message,true))}$('resultTab').onclick=()=>switchMode('results');$('requestTab').onclick=()=>switchMode('requests');
$('resultPrev').onclick=()=>{resultOffset=Math.max(0,resultOffset-25);loadResults().catch(e=>notice(e.message,true))};$('resultNext').onclick=()=>{resultOffset+=25;loadResults().catch(e=>notice(e.message,true))};
async function downloadExport(format){const p=resultParams();p.set('mode',resultMode);p.set('format',format);const btn=$(format==='csv'?'exportCsv':'exportJson');btn.disabled=true;try{notice('正在导出全部筛选数据…');const r=await fetch('/api/serp/export?'+p);if(!r.ok){const d=await r.json();throw Error(d.error||'导出失败')}saveBlob(await r.blob(),`google-${resultMode}.${format}`);notice('导出完成：全部符合筛选的数据')}catch(e){notice(e.message,true)}finally{btn.disabled=false}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('exportJson').onclick=()=>downloadExport('jsonl');$('exportCsv').onclick=()=>downloadExport('csv');
document.addEventListener('click',async e=>{const result=e.target.closest('[data-results]');if(result){$('resultCampaign').value=result.dataset.results;resultOffset=0;location.hash='results';if(view==='results')loadResults().catch(e=>notice(e.message,true))}const b=e.target.closest('[data-json]');if(!b)return;b.disabled=true;try{currentJson=await api('/api/serp/requests/'+b.dataset.json);$('jsonText').textContent=JSON.stringify(currentJson,null,2);$('jsonDialog').showModal()}catch(e){notice(e.message,true)}finally{b.disabled=false}});$('closeJson').onclick=()=>$('jsonDialog').close();$('downloadJson').onclick=()=>{if(currentJson)saveBlob(new Blob([JSON.stringify(currentJson,null,2)],{type:'application/json'}),'google-'+currentJson.search_metadata.id+'.json')};
$('settingsForm').addEventListener('input',()=>{settingsDirty=true;$('settingsSaved').textContent='有未保存修改'});$('settingsForm').addEventListener('change',()=>{settingsDirty=true;$('settingsSaved').textContent='有未保存修改'});
$('settingsForm').addEventListener('submit',async e=>{e.preventDefault();$('saveSettings').disabled=true;try{await api('/api/collector-settings',{content_fetch_enabled:$('bodySwitch').checked,continuous_enabled:$('continuousSwitch').checked,continuous_sources:[...document.querySelectorAll('[name=continuousSource]:checked')].map(x=>x.value),continuous_keywords:$('continuousKeywords').value.split('\n').map(x=>x.trim()).filter(Boolean),web_region:$('settingsWebRegion').value,web_language:$('settingsWebLanguage').value,news_locales:$('settingsNewsLocales').value.split(',').map(x=>x.trim()).filter(Boolean),trends_geos:$('settingsTrendsGeos').value.split(',').map(x=>x.trim().toUpperCase()).filter(Boolean),web_max_pages:Number($('webPages').value),news_interval_seconds:Number($('newsInterval').value),trends_interval_seconds:Number($('trendsInterval').value)});settingsDirty=false;await loadSettings(true);notice('设置已保存并应用；后续批次生效，持续供给最多 30 秒读取')}catch(e){notice(e.message,true)}finally{$('saveSettings').disabled=false}});
let autoToggleBusy=false;
$('autoToggle').onclick=async()=>{if(autoToggleBusy||autoEnabled===null)return;autoToggleBusy=true;$('autoToggle').disabled=true;try{const enabled=!autoEnabled;await api('/api/collector-settings',{continuous_enabled:enabled});await loadSettings();if(!settingsDirty)$('continuousSwitch').checked=enabled;notice(enabled?'自动采集已开启':'自动采集已关闭，已采集数据保留。已发出的请求允许完成。');if(view==='tasks')await loadTasks()}catch(e){notice(e.message,true)}finally{autoToggleBusy=false;$('autoToggle').disabled=false}};
async function loadLatest(){const d=await api('/api/serp/results?limit=10&count_total=false');$('latestRows').innerHTML=d.rows.map(x=>{const a=x.data,tr=x.source==='google_trends';return `<article class="result ${x.source.replace('google_','')}"><div class="result-meta"><span class="badge">${names[x.source]}</span><span>${time(x.completed_at)}</span><span>关键词：${esc(x.query)}</span></div>${tr?`<h3>${esc(a.keyword||'未知热门话题')}</h3><ul>${(a.articles||[]).slice(0,5).map(b=>`<li><a href="${safeLink(b.link)}" target="_blank" rel="noopener noreferrer">${esc(b.title||b.link)}</a></li>`).join('')||'<li>此话题暂无报道链接</li>'}</ul>`:`<h3><a href="${safeLink(a.link)}" target="_blank" rel="noopener noreferrer">${esc(a.title||a.link||'未知标题')}</a></h3><div class="help">${esc(a.link)}</div>${a.snippet?`<p>${esc(a.snippet)}</p>`:''}${a.link_status==='google_news_redirect'?'<p class="help">Google 新闻跳转链接</p>':''}`}<button class="mini secondary" data-json="${esc(x.id)}">查看详细数据</button></article>`}).join('')||'<div class="panel empty">还没有采集数据。到“任务”页输入关键词开始采集。</div>'}
$('refreshLatest').onclick=async()=>{$('refreshLatest').disabled=true;try{await loadLatest();notice('最新数据已刷新')}catch(e){notice(e.message,true)}finally{$('refreshLatest').disabled=false}};

let whaleOffset=0,whaleTotal=0,whaleDirty=false,whaleReceiptJob=null,whaleReceiptOffset=0;
const whaleStates={active:'处理中',paused:'已暂停',stopped:'已停止',succeeded:'上传流程完成',failed:'失败 / 需处理'};
async function loadWhale(){const [s,d]=await Promise.all([api('/api/whale/status'),api('/api/whale/jobs?limit=20&offset='+whaleOffset)]);const cfg=s.settings;
$('whaleConnection').textContent=(s.configured?'已配置平台凭据':'尚未配置平台凭据')+' / 数据集 '+s.dataset_id+' / 来源 '+s.source_platform;
if(!whaleDirty){$('whaleUploadSwitch').checked=cfg.uploads_enabled;$('whaleClaimSwitch').checked=cfg.claims_enabled}
$('whaleRuntime').textContent=(cfg.runtime.connected_at?'最近连接 '+time(cfg.runtime.connected_at):'尚未连接，开关默认关闭')+(cfg.runtime.last_error?' / 异常 '+cfg.runtime.last_error:'');
$('whalePending').textContent=fmt(s.counts.pending);$('whaleReceived').textContent=fmt((s.counts.queued||0)+(s.counts.accepted||0));$('whaleDuplicate').textContent=fmt(s.counts.duplicate);$('whaleRejected').textContent=fmt(s.counts.rejected);whaleTotal=d.total;
$('whaleJobs').innerHTML=d.jobs.map(x=>{const c=x.counts;let actions=x.status==='active'?'<button class="mini secondary" data-whale-op="pause">暂停</button>':x.status==='paused'?'<button class="mini" data-whale-op="resume">继续</button>':x.status==='failed'?'<button class="mini" data-whale-op="retry">重试</button>':'';if(['active','paused','failed'].includes(x.status))actions+='<button class="mini danger" data-whale-op="stop">停止</button>';const waiting=x.status==='active'&&!cfg.uploads_enabled?' / 上传开关已关闭':'';return `<tr data-whale-id="${esc(x.id)}"><td>${x.kind==='platform'?'平台下发任务':x.automatic?'采集任务同步上传':'已采集数据上传'}<div class="help">${esc(x.platform_task_id||x.id)}<br>${time(x.created_at)}</div><details><summary>任务参数</summary><pre>${esc(JSON.stringify(x.specification,null,2))}</pre></details></td><td>${esc(whaleStates[x.status]||x.status)}${waiting}<div class="help">${esc(x.last_error||'')}</div></td><td>${fmt(x.collected)}</td><td>${fmt(x.received)} / ${fmt(x.duplicates)}</td><td>${fmt(c.pending)} / ${fmt(c.rejected)}</td><td><div class="row-actions">${actions}<button class="mini secondary" data-whale-receipts="${esc(x.id)}">数据与回执</button></div></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">还没有上传任务。可选择已采集数据加入队列。</td></tr>';
$('whaleJobCount').textContent=`共 ${fmt(d.total)} 个任务，当前 ${d.total?whaleOffset+1:0}–${Math.min(whaleOffset+20,d.total)}`;$('whalePrev').disabled=whaleOffset===0;$('whaleNext').disabled=whaleOffset+20>=d.total}
$('whaleSettingsForm').addEventListener('change',()=>whaleDirty=true);
$('whaleSettingsForm').addEventListener('submit',async e=>{e.preventDefault();$('saveWhaleSettings').disabled=true;try{await api('/api/whale/settings',{uploads_enabled:$('whaleUploadSwitch').checked,claims_enabled:$('whaleClaimSwitch').checked});whaleDirty=false;await loadWhale();notice('平台开关已保存，系统自动采集设置未改变')}catch(e){notice(e.message,true)}finally{$('saveWhaleSettings').disabled=false}});
$('whaleUploadForm').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const p={limit:Number($('whaleLimit').value),new_only:$('whaleNewOnly').checked,start:b.value!=='draft'};for(const [field,id] of [['source','whaleSource'],['q','whaleQuery'],['campaign_id','whaleCampaign']])if($(id).value.trim())p[field]=$(id).value.trim();if($('whaleSince').value)p.since=$('whaleSince').value+'T00:00:00Z';if($('whaleUntil').value){const end=new Date($('whaleUntil').value+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+1);p.until=end.toISOString()}const job=await api('/api/whale/jobs',p);whaleOffset=0;await loadWhale();notice('已保存 '+fmt(job.collected)+' 个链接。上传开关关闭时，数据保留在队列等待。')}catch(e){notice(e.message,true)}finally{b.disabled=false}});
async function loadWhaleReceipts(){const d=await api(`/api/whale/jobs/${whaleReceiptJob}/receipts?limit=50&offset=${whaleReceiptOffset}`);$('whaleReceipts').textContent=JSON.stringify(d.receipts,null,2);$('whaleReceiptPrev').disabled=whaleReceiptOffset===0;$('whaleReceiptNext').disabled=d.receipts.length<50}
$('whaleJobs').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;b.disabled=true;try{if(b.dataset.whaleOp){await api(`/api/whale/jobs/${b.closest('[data-whale-id]').dataset.whaleId}/${b.dataset.whaleOp}`,{});await loadWhale();notice('任务操作已保存')}else if(b.dataset.whaleReceipts){whaleReceiptJob=b.dataset.whaleReceipts;whaleReceiptOffset=0;await loadWhaleReceipts();$('whaleReceiptDialog').showModal()}}catch(e){notice(e.message,true)}finally{b.disabled=false}});
$('closeWhaleReceipts').onclick=()=>$('whaleReceiptDialog').close();$('whaleReceiptPrev').onclick=()=>{whaleReceiptOffset=Math.max(0,whaleReceiptOffset-50);loadWhaleReceipts().catch(e=>notice(e.message,true))};$('whaleReceiptNext').onclick=()=>{whaleReceiptOffset+=50;loadWhaleReceipts().catch(e=>notice(e.message,true))};
$('refreshWhale').onclick=()=>loadWhale().catch(e=>notice(e.message,true));$('whalePrev').onclick=()=>{whaleOffset=Math.max(0,whaleOffset-20);loadWhale().catch(e=>notice(e.message,true))};$('whaleNext').onclick=()=>{whaleOffset+=20;loadWhale().catch(e=>notice(e.message,true))};

const refreshing=new Set();async function refreshView(){const current=view;if(refreshing.has(current))return;refreshing.add(current);try{const jobs=[loadSettings()];if(current==='overview')jobs.push(loadLatest(),loadOverview());if(current==='tasks')jobs.push(loadTasks());if(current==='results')jobs.push(loadResults());if(current==='whale')jobs.push(loadWhale());await Promise.all(jobs);if(view===current)$('updated').textContent='每 10 秒刷新 / 最近读取 '+new Date().toLocaleTimeString('zh-CN')}catch(e){notice(e.message,true);$('resultRows').setAttribute('aria-busy','false');if(current==='overview'&&$('latestRows').querySelector('.loading'))$('latestRows').innerHTML='<div class="panel empty">数据读取失败，请点击“刷新数据”重试。</div>';$('updated').textContent='连接失败，10 秒后重试'}finally{refreshing.delete(current)}}
window.addEventListener('hashchange',showView);showView();setInterval(refreshView,10000);
</script></body></html>'''


def page(existing_html: str = '') -> str:
    return PAGE
